// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * M-F5: ORDER BY expressions compile natively through a hidden computed sort-key slot. Evaluation errors order as
 * unbound (first under ASC, last under DESC — the generic ValueComparator's null-first rule), ties are compared
 * tie-aware (asserted as sets), and the hidden slot never leaks into result binding names.
 */
public class LmdbNativeOrderByExpressionTest {

	private static final String EX = "http://example.com/";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			IRI val = vf.createIRI(EX, "val");
			conn.add(vf.createIRI(EX, "s1"), val, vf.createLiteral(1));
			conn.add(vf.createIRI(EX, "s2"), val, vf.createLiteral(2));
			conn.add(vf.createIRI(EX, "s3"), val, vf.createLiteral(3));
			conn.add(vf.createIRI(EX, "s4"), val, vf.createLiteral("abc"));
			conn.add(vf.createIRI(EX, "s5"), val, vf.createLiteral("1"));
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	private List<String> subjects(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(row -> row.getValue("s").stringValue().substring(EX.length()))
					.collect(Collectors.toList());
		}
	}

	/** DESC over an arithmetic expression: numeric keys sort descending; error rows order as unbound (last). */
	@Test
	public void orderByDescExpressionCompilesNativelyAndSortsCorrectly() {
		String query = "SELECT ?s WHERE { ?s <" + EX + "val> ?v } ORDER BY DESC(?v * 2)";
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		List<String> subjects = subjects(query);
		assertThat(subjects).hasSize(5);
		assertThat(subjects.subList(0, 3)).containsExactly("s3", "s2", "s1");
		assertThat(subjects.subList(3, 5)).containsExactlyInAnyOrder("s4", "s5");
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("ORDER BY DESC(expr) must compile natively (previously a root decline)")
				.isGreaterThanOrEqualTo(1);
	}

	/** ASC: error rows (unbound keys) sort first, before every bound key. */
	@Test
	public void orderByAscExpressionOrdersErrorsFirst() {
		String query = "SELECT ?s WHERE { ?s <" + EX + "val> ?v } ORDER BY (?v * 2)";
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		List<String> subjects = subjects(query);
		assertThat(subjects).hasSize(5);
		assertThat(subjects.subList(0, 2)).containsExactlyInAnyOrder("s4", "s5");
		assertThat(subjects.subList(2, 5)).containsExactly("s1", "s2", "s3");
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("ORDER BY (expr) must compile natively")
				.isGreaterThanOrEqualTo(1);
	}

	/** STR keys with a tie under LIMIT: both "1"-keyed rows fill the first two positions, in either order. */
	@Test
	public void orderByStrExpressionWithLimitIsTieAware() {
		String query = "SELECT ?s WHERE { ?s <" + EX + "val> ?v } ORDER BY STR(?v) LIMIT 2";
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		List<String> subjects = subjects(query);
		assertThat(subjects).containsExactlyInAnyOrder("s1", "s5");
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("ORDER BY STR(expr) LIMIT must compile natively")
				.isGreaterThanOrEqualTo(1);
	}

	/** The hidden sort-key slot never leaks into result binding names. */
	@Test
	public void hiddenSortKeySlotNeverLeaks() {
		String query = "SELECT ?s ?v WHERE { ?s <" + EX + "val> ?v } ORDER BY DESC(?v * 2)";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			for (BindingSet row : QueryResults.asList(conn.prepareTupleQuery(query).evaluate())) {
				assertThat(row.getBindingNames()).containsExactlyInAnyOrder("s", "v");
			}
		}
	}
}
